mapper.sql:
WHERE purchase_orders.status > 0 AND purchase_orders.is_approve = 1
AND purchase_orders.id NOT IN (
SELECT purchase_order_id
FROM purchase_receive_results
WHERE status > 0
AND type = 2
AND purchase_order_id IS NOT NULL
)
AND purchase_orders.company_id IN (
SELECT company_id
FROM user_companies
WHERE user_id = #{filter.userId}
)

    AND purchase_orders.location_group_id = #{filter.warehouseId}


    AND purchase_orders.location_id = #{filter.locationId}


    AND purchase_orders.status = #{filter.status}


    AND purchase_orders.po_type = #{filter.purchasing}


    AND (
    purchase_orders.po_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR purchase_requests.pr_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR vendors.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR locations.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )

mapper.select:
SELECT



GROUP BY purchase_orders.id
ORDER BY


        ${filter.orderBy}


        purchase_orders.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

